module Datapath_Unit_2_Beh #(parameter dp_width = 8, R2_width = 4)(  output [R2_width -1: 0] 	count,   output 						Zero,  input [dp_width -1: 0] 		data,   input 						Load_regs, Add_shift, clock, reset_b);  reg [dp_width -1: 0] 			R1;  reg [R2_width -1: 0] 		R2;  assign count = R2;  assign Zero = ~|R1;  always @ (posedge clock, negedge reset_b)    begin      if (reset_b == 0) begin R1 <= 0; R2 <= 0; end else begin        if (Load_regs) begin R1 <= data; R2 <= 0; end        if (Add_shift) begin R1 <= R1 >> 1; R2 <= R2 + R1[0]; end	// concurrent operations      end    endendmodule// Test plan for datapath unit// Verify active-low reset action// Test for action of Add_shift// Test for action of Load_regsmodule t_Datapath_Unit_2_Beh();  parameter R1_size = 8, R2_size = 4;   wire	[R2_size -1: 0]	count;  wire						Zero;  reg	[R1_size -1: 0]	data;   reg						Load_regs, Add_shift, clock, reset_b;  Datapath_Unit_2_Beh M0 (count, Zero, data, Load_regs, Add_shift, clock, reset_b);  initial #1000 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork    #1 reset_b = 1;    #3 reset_b = 0;    #4 reset_b = 1;  join  initial fork    data = 8'haa;    Load_regs = 0;    Add_shift = 0;    #10 Load_regs = 1;    #20 Load_regs = 0;    #50 Add_shift = 1;    #150 Add_shift  = 0;  joinendmodule